78	// Normalize text for comparison (lowercase, remove punctuation, extra spaces)
79	function normalizeText(text: string): string {
80	  return text
81	    .toLowerCase()
82	    .replace(/[^a-z0-9\s]/g, "")
83	    .replace(/\s+/g, " ")
84	    .trim();
