87	// Levenshtein distance for fuzzy matching
88	function levenshteinDistance(a: string, b: string): number {
89	  const matrix: number[][] = [];
90	  for (let i = 0; i <= b.length; i++) {
91	    matrix[i] = [i];
92	  }
93	  for (let j = 0; j <= a.length; j++) {
94	    matrix[0][j] = j;
95	  }
96	  for (let i = 1; i <= b.length; i++) {
97	    for (let j = 1; j <= a.length; j++) {
98	      if (b.charAt(i - 1) === a.charAt(j - 1)) {
99	        matrix[i][j] = matrix[i - 1][j - 1];
100	      } else {
101	        matrix[i][j] = Math.min(
102	          matrix[i - 1][j - 1] + 1,
103	          matrix[i][j - 1] + 1,
104	          matrix[i - 1][j] + 1,
105	        );
106	      }
107	    }
108	  }
109	  return matrix[b.length][a.length];
110	}
